using System;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
namespace SlopProX {
 public sealed class GlobalTracksPanel:ScaledCanvas {
  public Func<ProjectDocument> Project;public Func<int> Header,Zoom;public Func<double> First;public event EventHandler EditRequested;private bool _resize;private int _screenY,_initial;
  public GlobalTracksPanel(){BackColor=Color.FromArgb(48,48,48);DoubleBuffered=true;Cursor=Cursors.HSplit;Font=new Font("Segoe UI",8);}
  protected override void OnPaint(PaintEventArgs e){PreparePaint(e);e.Graphics.Clear(BackColor);using(var pen=new Pen(Color.FromArgb(101,101,101)))e.Graphics.DrawLine(pen,0,3,Width,3);if(Height<20||Project==null)return;var project=Project();int header=Header();int zoom=Zoom();double first=First();string[] labels={"Global Tracks","Tempo","Signature","Chords"};for(int row=0;row<4;row++){int y=8+row*24;using(var pen=new Pen(Color.FromArgb(34,34,34)))e.Graphics.DrawLine(pen,0,y+23,Width,y+23);StudioDraw.Label(e.Graphics,labels[row],Font,new Rectangle(8,y,header-15,22),Color.Gainsboro,TextFormatFlags.VerticalCenter);if(row==1){using(var pen=new Pen(Color.FromArgb(125,169,207)))e.Graphics.DrawLine(pen,header,y+12,Width,y+12);StudioDraw.Label(e.Graphics,project.Tempo.ToString("0.0")+" BPM",Font,new Rectangle(header+8,y,120,22),Color.FromArgb(206,226,241),TextFormatFlags.VerticalCenter);}else if(row==2)StudioDraw.Label(e.Graphics,project.TimeSignatureNumerator+" / "+project.TimeSignatureDenominator,Font,new Rectangle(header+8,y,100,22),Color.Gainsboro,TextFormatFlags.VerticalCenter);else if(row==3){foreach(var chord in project.Studio.Chords){int x=header+(int)((chord.Beat-first)*zoom),w=Math.Max(36,(int)(chord.Length*zoom));if(x+w<header||x>Width)continue;Rectangle rect=Rectangle.Intersect(new Rectangle(x,y+2,w-2,19),new Rectangle(header,y,Math.Max(0,Width-header),24));if(rect.Width<1)continue;using(var b=new SolidBrush(Color.FromArgb(91,104,73)))e.Graphics.FillRectangle(b,rect);StudioDraw.Label(e.Graphics,chord.Name,Font,rect,Color.FromArgb(229,239,216),TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);}}else StudioDraw.Label(e.Graphics,"Double-click to edit tempo, meter and chords",Font,new Rectangle(header+8,y,Math.Max(0,Width-header-12),22),Color.Silver,TextFormatFlags.VerticalCenter);}}
  protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Left&&e.Y<9*CanvasScale){_resize=true;_screenY=MousePosition.Y;_initial=base.Height;Capture=true;}else if(e.Button==MouseButtons.Right&&EditRequested!=null)EditRequested(this,EventArgs.Empty);}
  protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(_resize)base.Height=Math.Max(8,Math.Min((int)(145*CanvasScale),_initial+MousePosition.Y-_screenY));else Cursor=e.Y<9*CanvasScale?Cursors.HSplit:Cursors.Default;}
  protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(_resize){_resize=false;Capture=false;if(base.Height<35*CanvasScale)base.Height=8;}}
  protected override void OnMouseDoubleClick(MouseEventArgs e){base.OnMouseDoubleClick(e);if(EditRequested!=null)EditRequested(this,EventArgs.Empty);}
 }
 public sealed partial class MainForm {
  private void EditGlobalTracks(object sender,EventArgs args){using(var dialog=new Form{Text=UiText.Translate("Global Tracks"),ClientSize=new Size(580,270),BackColor=Color.FromArgb(53,53,55),ForeColor=Color.Gainsboro,StartPosition=FormStartPosition.CenterParent,Font=new Font("Segoe UI",10)}){var tempo=new NumericUpDown{Left=195,Top=22,Width=110,Minimum=20,Maximum=400,DecimalPlaces=1,Value=(decimal)_project.Tempo,BackColor=Color.FromArgb(36,36,38),ForeColor=Color.Gainsboro};var numerator=new NumericUpDown{Left=195,Top=65,Width=74,Minimum=1,Maximum=32,Value=_project.TimeSignatureNumerator,BackColor=Color.FromArgb(36,36,38),ForeColor=Color.Gainsboro};var denominator=new StudioChoice{Left=283,Top=65,Width=74};denominator.Items.AddRange(new object[]{1,2,4,8,16,32});denominator.SelectedItem=_project.TimeSignatureDenominator;var chords=new TextBox{Left=20,Top=132,Width=535,Text=String.Join(" | ",_project.Studio.Chords.Select(c=>c.Name).ToArray()),BackColor=Color.FromArgb(34,34,36),ForeColor=Color.Gainsboro};if(chords.Text.Length==0)chords.Text="C | Am | F | G";dialog.Controls.Add(new Label{Text="Tempo (BPM)",Left=20,Top=24,Width=170});dialog.Controls.Add(new Label{Text="Time Signature",Left=20,Top=67,Width=170});dialog.Controls.Add(new Label{Text="Chord progression — one chord per bar",Left=20,Top=105,Width=530});dialog.Controls.Add(tempo);dialog.Controls.Add(numerator);dialog.Controls.Add(denominator);dialog.Controls.Add(chords);var generate=new CheckBox{Text="Create MIDI chord track",Checked=false,Left=20,Top=172,Width=320};var apply=new Button{Text="Apply",Left=410,Top=216,Width=145,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(70,113,149)};apply.Click+=delegate{try{double bar=(int)numerator.Value*4.0/Convert.ToInt32(denominator.SelectedItem);var after=_project.Studio.Copy();after.Chords=ChordProgression.Parse(chords.Text,bar);SetTempo((double)tempo.Value);SetMeter((int)numerator.Value,Convert.ToInt32(denominator.SelectedItem));var commands=new System.Collections.Generic.List<IProjectCommand>{new SetStudioCommand("Edit chord progression",_project.Studio,after)};if(generate.Checked)commands.Add(new AddTrackCommand(ChordProgression.CreateTrack(after.Chords),_project.Tracks.Count));_history.Execute(_project,new CompositeCommand("Global tracks",commands));RefreshState();_globalTracks.Invalidate();dialog.Close();}catch(Exception ex){MessageBox.Show(dialog,UiText.Translate(ex.Message),UiText.Translate("Chords"));}};dialog.Controls.Add(generate);dialog.Controls.Add(apply);dialog.AcceptButton=apply;UiText.Apply(dialog);dialog.ShowDialog(this);}}
 }
}
